let returnMode='live';let state,db,mode='live',route={page:'overview'},invoiceFilter='all',search='',reportStart=today().slice(0,7)+'-01',reportEnd=today(),editLines=[],working=false,switching=false,offlineReady=false,offlineState='checking',toastTimer;
const app=$('#app'),modal=$('#modal');
try{document.documentElement.dataset.theme=localStorage.getItem('invoiceflow-theme')||'light'}catch{}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',5500)}
function failure(error){console.error(error);toast(error.message||'Something went wrong. Your changes were not saved.')}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('invoiceflow',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspaces');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Device storage is unavailable. Open in a regular browser window with storage enabled.'))})}
function load(key){return new Promise((resolve,reject)=>{const t=db.transaction('workspaces','readonly'),r=t.objectStore('workspaces').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function commit(change,{checkpoint=false,workspaceSwitch=false}={}){if(switching&&!workspaceSwitch)throw Error('A workspace switch is in progress. Try again in a moment.');if(working)throw Error('A save is already in progress. Try again in a moment.');working=true;const key=mode;try{const draft=structuredClone(state);change(draft);draft.revision=state.revision+1;validateState(draft);makeBackup(draft,key);await new Promise((resolve,reject)=>{const t=db.transaction('workspaces','readwrite'),store=t.objectStore('workspaces'),r=store.get(key);let conflict=false;r.onsuccess=()=>{if((r.result?.revision||0)!==state.revision){conflict=true;t.abort();return}if(checkpoint)store.put(structuredClone(state),key+'-before-restore');store.put(draft,key)};t.oncomplete=resolve;t.onabort=()=>reject(Error(conflict?'This workspace changed in another tab. Reload before saving to avoid overwriting changes.':'Could not save. Device storage may be full. Export a backup before closing.'));t.onerror=()=>reject(Error('Could not save to device storage. Your changes were not saved.'))});state=draft;return draft}finally{working=false}}
async function switchMode(){if(working||switching)return;switching=true;const previousMode=mode,previousState=state,target=mode==='demo'?returnMode:'demo';try{const stored=await load(target),incoming=stored||(target==='demo'?demoState():emptyState());validateState(incoming);if(previousMode!=='demo')returnMode=previousMode;mode=target;state=incoming;if(!stored)await commit(()=>{},{workspaceSwitch:true});route={page:'overview'};invoiceFilter='all';search='';render();toast(mode==='demo'?'Example data · isolated from your real workspace.':'Back in your real workspace.')}catch(error){mode=previousMode;state=previousState;throw error}finally{switching=false}}
const pages=[['overview','grid','Overview'],['invoices','invoice','Invoices'],['quotes','invoice','Quotes'],['collections','clock','Collections'],['expenses','expense','Expenses'],['customers','users','Customers'],['items','box','Items'],['reports','chart','Reports']];
function render(){const current=route.quote||route.page==='quote'?'quotes':route.page==='editor'||route.page==='invoice'?'invoices':route.page;document.title=`${current[0].toUpperCase()+current.slice(1)} · InvoiceFlow`;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt="">InvoiceFlow</div><div class="nav-label">Your workspace</div><nav aria-label="Main navigation">${pages.map(([p,i,label])=>`<button class="nav-item ${p===current?'active':''}" data-page="${p}" ${p===current?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}<button class="nav-item ${current==='settings'?'active':''}" data-page="settings" ${current==='settings'?'aria-current="page"':''}>${icon('settings')}<span>Settings</span></button></nav><div class="side-bottom"><div class="local-status"><div><span class="dot"></span>Saved on this device</div><div>No account. No data uploads.</div><button class="link-button small" data-action="businesses">Switch business</button></div><button class="nav-item" data-action="demo">${icon(mode==='demo'?'arrow':'box')}<span>${mode==='demo'?'Exit demo workspace':'Explore with sample data'}</span></button></div></aside><div class="workspace"><header class="topbar"><div class="crumb">Workspace <span>/</span> <strong>${esc(pages.find(p=>p[0]===current)?.[2]||'Settings')}</strong></div><div class="mobile-brand"><img src="icon.svg" alt="">InvoiceFlow</div><div class="top-right"><span class="tag">${mode==='demo'?'DEMO WORKSPACE':'LOCAL FIRST · ZAR'}</span><button class="icon-btn" data-action="theme" aria-label="Toggle light or dark mode">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="avatar" data-page="settings" aria-label="Business settings">${esc((state.business.name||'You').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</button></div></header><main class="content" id="main" tabindex="-1">${mode==='demo'?`<div class="banner demo-banner"><span><strong>Demo workspace.</strong> These are example records. Your real data is separate.</span><button class="btn small" data-action="demo">Exit demo ${icon('arrow')}</button></div>`:''}${renderPage()}<footer class="footer"><span>InvoiceFlow <span aria-hidden="true">·</span> A little less admin.</span><span><span id="offline-footer">${offlineReady?'Offline ready · ':''}</span>Device only. Back up regularly. <button class="link-button small" data-action="backup">Export backup ${icon('up')}</button></span></footer></main></div></div>`;bindPage();}
function heading(title,subtitle,actions='',eyebrow='YOUR MONEY, AT A GLANCE'){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`}
const btn=(label,action,primary=false,i='',extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${i?icon(i):''}${label}</button>`;
function renderPage(){switch(route.page){case'quotes':return quotesPage();case'quote':return quotePage();case'collections':return collectionsPage();case'overview':return overview();case'invoices':return invoicesPage();case'customers':return customersPage();case'items':return itemsPage();case'expenses':return expensesPage();case'settings':return settingsPage();case'editor':return editorPage();case'invoice':return invoicePage();case'reports':return reportsPage();default:return overview()}}
function empty(i,title,text,action=''){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h3>${title}</h3><p>${text}</p>${action}</div>`}
function pill(i){const s=status(i),labels={draft:'Draft',sent:'Sent',paid:'Paid',overdue:'Overdue',partial:'Part paid',void:'Voided',credited:'Credited'};return `<span class="pill ${s}"><span aria-hidden="true">${s==='paid'?'✓':'·'}</span>${labels[s]}</span>`}
function invoiceTable(list,compact=false){if(!list.length)return empty('invoice','No invoices here yet','Create an invoice, add your work, and keep track of what comes next.',btn('Create invoice','new-invoice',true,'plus'));return `<div class="table-wrap"><table><thead><tr><th>Invoice / customer</th>${compact?'':'<th>Issued</th>'}<th>Due date</th><th>Status</th><th class="num">${compact?'Balance':'Total / balance'}</th></tr></thead><tbody>${list.map(i=>`<tr><td><button class="link-button" data-view="${i.id}">${esc(i.number)}</button><div class="muted">${esc(i.customer.name)}</div></td>${compact?'':`<td>${date(i.date)}</td>`}<td>${date(i.due)}</td><td>${pill(i)}</td><td class="num"><strong>${money(i.state==='void'?0:balance(i))}</strong>${compact?'':`<div class="muted">${money(total(i))} total</div>`}</td></tr>`).join('')}</tbody></table></div>`}
function stat(label,value,note,i,accent=false){return `<div class="stat ${accent?'accent':''}"><div class="stat-label"><span>${label}</span>${icon(i)}</div><div class="stat-value ${money(value).length>14?'long-amount':''}">${money(value)}</div><div class="stat-note">${note}</div></div>`}
function overview(){const start=today().slice(0,7)+'-01',s=cashSummary(state,start,today()),unpaid=state.invoices.filter(i=>i.state==='issued'&&balance(i)>0),late=unpaid.filter(i=>status(i)==='overdue'),recent=[...state.invoices].reverse().slice(0,5);return `${heading('A clear view of your business.','Less chasing numbers. More doing your thing.',btn('New invoice','new-invoice',true,'plus'))}${!state.business.name?`<div class="banner"><span><strong>Make this space yours.</strong> Add your business details to create your first invoice.</span>${btn('Set up business','setup',false,'arrow')}</div>`:''}<div class="stats">${stat('Outstanding',s.outstanding,`${unpaid.length} unpaid invoice${unpaid.length===1?'':'s'}`,'invoice',true)}${stat('Received this month',s.income,'Payments recorded · cash basis','down')}${stat('Expenses this month',s.expenses,'Money out · cash basis','up')}${stat('Overdue',s.overdue,`${late.length} invoice${late.length===1?'':'s'} to follow up`,'clock')}</div><div class="grid-main"><div><section class="panel"><div class="panel-head"><h2>Recent invoices</h2><button class="link-button small" data-page="invoices">View all ${icon('arrow')}</button></div>${invoiceTable(recent,true)}</section><section class="panel"><div class="panel-head"><h2>Recent expenses</h2><button class="link-button small" data-action="new-expense">Add expense +</button></div>${state.expenses.length?`<div class="table-wrap"><table><tbody>${[...state.expenses].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(e=>`<tr><td><strong>${esc(e.description)}</strong><div class="muted">${esc(e.category)} · ${date(e.date)}</div></td><td class="num">${money(e.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('expense','Every expense, accounted for','Add software, supplies or your next client coffee.',btn('Add expense','new-expense',false,'plus'))}</section></div><div class="dashboard-secondary"><section class="panel"><div class="panel-head"><h2>Money in. Money out.</h2><span class="small muted">6 months</span></div><div class="panel-body">${chart()}<div class="summary-row section-gap"><span class="muted">Received this month</span><span>${money(s.income)}</span></div><div class="summary-row"><span class="muted">Expenses this month</span><span>${money(s.expenses)}</span></div><div class="summary-row total"><span>Net cash this month</span><span>${money(s.net)}</span></div><p class="form-note">Recorded receipts minus expenses. This is a cash summary, not a full accounting profit calculation.</p></div></section><div class="helper-card">${icon('lock')}<h3 class="section-gap">Your work. Your records.</h3><p>Your records stay in this browser. Download a backup to keep them safe when you change or clear your device.</p>${btn('Export backup','backup',false,'download')}<p class="form-note">${mode==='demo'?'Just exploring? Switch back to your real workspace when ready.':'Want to look around first?'} <button class="link-button small" data-action="demo">${mode==='demo'?'Exit demo':'Try sample data'}</button></p></div></div></div>`}
function chart(){const d=new Date(today()+'T12:00:00Z');const months=Array.from({length:6},(_,n)=>{const from=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-5+n,1)),to=new Date(Date.UTC(from.getUTCFullYear(),from.getUTCMonth()+1,0)),label=from.toLocaleDateString('en-ZA',{month:'short'}),a=from.toISOString().slice(0,10),b=to.toISOString().slice(0,10),s=cashSummary(state,a,b);return {...s,label}}),max=Math.max(1,...months.flatMap(m=>[m.income,m.expenses]));return `<div class="cash-chart" role="img" aria-label="${esc(months.map(m=>`${m.label}: received ${money(m.income)}, expenses ${money(m.expenses)}`).join('; '))}">${months.map(m=>`<div class="chart-group" title="${esc(m.label+': received '+money(m.income)+', expenses '+money(m.expenses))}"><div class="bar" style="height:${Math.max(1,m.income/max*100)}%"></div><div class="bar expense" style="height:${Math.max(1,m.expenses/max*100)}%"></div></div>`).join('')}</div><div class="chart-labels">${months.map(m=>`<span>${m.label}</span>`).join('')}</div><div class="legend"><span><i></i>Received</span><span><i class="expense"></i>Expenses</span></div>`}
function invoicesPage(){return `${heading('Invoices','From your first draft to your last payment.',btn('Export CSV','export-invoices',false,'download')+btn('New invoice','new-invoice',true,'plus'),'GET PAID FOR YOUR WORK')}<div class="toolbar"><div class="filters" role="group" aria-label="Filter invoices">${[['all','All'],['draft','Draft'],['sent','Sent'],['partial','Part paid'],['overdue','Overdue'],['paid','Paid'],['void','Voided'],['credited','Credited']].map(([k,l])=>`<button class="filter ${invoiceFilter===k?'active':''}" data-filter="${k}" aria-pressed="${invoiceFilter===k}">${l}</button>`).join('')}</div><input class="search" type="search" id="invoice-search" placeholder="Search customer or invoice…" aria-label="Search invoices" value="${esc(search)}"></div><section class="panel" id="invoice-results">${filteredInvoices()}</section>`}
function filteredInvoices(){let list=[...state.invoices].reverse().filter(i=>(invoiceFilter==='all'||status(i)===invoiceFilter)&&`${i.number} ${i.customer.name}`.toLowerCase().includes(search.toLowerCase()));return list.length?invoiceTable(list):empty('invoice',state.invoices.length?'No matching invoices':'Your next payday starts here',state.invoices.length?'Try another status or search term.':'Create a clear, professional invoice in a few simple steps.',btn('New invoice','new-invoice',true,'plus'))}
function customersPage(){return `${heading('Customers','Good relationships, with the details in one place.',btn('Add customer','new-customer',true,'plus'),'THE PEOPLE YOU WORK WITH')}<section class="panel">${state.customers.length?[...state.customers].sort((a,b)=>a.name.localeCompare(b.name)).map(c=>{const owed=state.invoices.filter(i=>i.customerId===c.id&&i.state==='issued').reduce((a,i)=>a+balance(i),0);return `<div class="list-card"><div><h3>${esc(c.name)}</h3><p>${esc(c.email||'No email added')}${c.address?'\n'+esc(c.address):''}</p></div><div class="text-right"><strong class="small">${money(owed)} outstanding</strong><div class="section-gap"><button class="btn small" data-statement="${c.id}">Statement</button><button class="btn small" data-edit-customer="${c.id}">Edit</button></div></div></div>`}).join(''):empty('users','A home for your customers','Save contact details once. Reuse them on every invoice.',btn('Add customer','new-customer',true,'plus'))}</section><p class="form-note">Issued invoices keep their original customer details. Updating a customer only affects new or edited drafts.</p>`}
function itemsPage(){return `${heading('Items & services','Your regular work, ready to add to an invoice.',btn('Add item','new-item',true,'plus'),'LESS REPEATING YOURSELF')}<section class="panel">${state.items.length?state.items.map(i=>`<div class="list-card"><div><h3>${esc(i.name)}</h3><p>${money(i.price)} per unit</p></div><div class="actions"><button class="btn small" data-edit-item="${i.id}">Edit</button><button class="icon-btn" data-delete-item="${i.id}" aria-label="Delete ${esc(i.name)}">${icon('trash')}</button></div></div>`).join(''):empty('box','Save your go-to work','Design hours, consulting sessions or products. Add what you invoice often.',btn('Add item','new-item',true,'plus'))}</section>`}
function expensesPage(){const sum=state.expenses.reduce((a,e)=>a+e.amount,0);return `${heading('Expenses','Keep the small costs from becoming a big mystery.',btn('Import CSV','import-expenses',false,'up')+btn('Add expense','new-expense',true,'plus'),'KNOW WHERE IT GOES')}<div class="toolbar"><span class="small muted">${state.expenses.length} expense${state.expenses.length===1?'':'s'} · ${money(sum)} recorded in total</span>${btn('Export CSV','export-expenses',false,'download')}</div><section class="panel">${state.expenses.length?`<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Date</th><th>Category</th><th class="num">Amount</th><th><span class="small">Actions</span></th></tr></thead><tbody>${[...state.expenses].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<tr><td><strong>${esc(e.description)}</strong></td><td>${date(e.date)}</td><td><span class="pill">${esc(e.category)}</span></td><td class="num">${money(e.amount)}</td><td><button class="link-button" data-edit-expense="${e.id}">Edit</button>${e.receipt?`<button class="btn small" data-receipt="${e.id}">Receipt</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('expense','A fresh start for your expenses','Add one by hand or bring your list across from a spreadsheet.',btn('Add expense','new-expense',true,'plus'))}</section><p class="form-note">Record business expenses in rand. Categories help organise your records; they do not determine tax deductibility.</p>`}
function reportsPage(){const s=cashSummary(state,reportStart,reportEnd),rows=CATEGORIES.map(c=>({name:c,amount:state.expenses.filter(e=>e.category===c&&e.date>=reportStart&&e.date<=reportEnd).reduce((a,e)=>a+e.amount,0)})).filter(c=>c.amount);return `${heading('The simple cash picture.','What came in, what went out, and what’s still owed.',btn('Export report','export-report',false,'download'),'REPORTS WITHOUT THE RABBIT HOLE')}<form id="report-form" class="toolbar"><div class="actions"><div class="field mb-0"><label for="report-start">From</label><input type="date" required id="report-start" value="${reportStart}"></div><div class="field mb-0"><label for="report-end">To</label><input type="date" required id="report-end" max="${today()}" value="${reportEnd}"></div><button class="btn primary" type="submit">Apply dates</button></div></form><div class="stats">${stat('Payments received',s.income,'Within the selected dates','down',true)}${stat('Expenses recorded',s.expenses,'Within the selected dates','up')}${stat('Net cash',s.net,'Receipts minus expenses','chart')}${stat('Still outstanding',s.outstanding,'All issued invoices · as of today','clock')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>Expenses by category</h2></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Category</th><th class="num">Recorded</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${c.name}</td><td class="num">${money(c.amount)}</td></tr>`).join('')}<tr><td><strong>Total expenses</strong></td><td class="num"><strong>${money(s.expenses)}</strong></td></tr></tbody></table></div>`:empty('chart','No expenses in this period','Change the dates or record an expense to see your breakdown.')}</section><div class="helper-card"><h3>What this report tells you</h3><p>Income is recorded when a payment is received, using the payment date. Expenses use the date you enter. Unpaid and draft invoices are not income.</p><p>Outstanding balances include all issued invoices, regardless of this date filter. Voided invoices are excluded.</p><p class="mb-0">This is a cash summary. It does not calculate accounting profit, tax liability, depreciation or your bank balance.</p></div></div>`}
function businessFields(b){return `<div class="form-grid"><div class="field span-2"><label for="business-name">Business / trading name *</label><input id="business-name" name="name" required maxlength="200" value="${esc(b.name)}" placeholder="e.g. Studio Mokoena" autocomplete="organization"></div><div class="field"><label for="business-email">Email</label><input id="business-email" name="email" type="email" maxlength="254" value="${esc(b.email)}" placeholder="hello@yourbusiness.co.za" autocomplete="email"></div><div class="field"><label for="business-phone">Phone</label><input id="business-phone" name="phone" type="tel" maxlength="100" value="${esc(b.phone)}" placeholder="+27…" autocomplete="tel"></div><div class="field span-2"><label for="business-address">Business address *</label><textarea id="business-address" name="address" required maxlength="1500" autocomplete="street-address" placeholder="Street address, city, postal code">${esc(b.address)}</textarea></div><div class="field span-2"><label for="business-bank">EFT / payment instructions</label><textarea id="business-bank" name="bank" maxlength="1500" placeholder="Bank name, account holder, account number, branch code…">${esc(b.bank)}</textarea><p class="form-note">Included on your invoice. Never enter passwords or banking login details.</p></div><div class="field span-2"><label for="business-notes">Default invoice note</label><textarea id="business-notes" name="notes" maxlength="3000">${esc(b.notes)}</textarea></div></div>`}
function settingsPage(){return `${heading('Make it yours.','The details that turn an invoice into your invoice.','','YOUR BUSINESS')}<div class="settings-wrap"><section class="panel"><form id="settings-form"><div class="form-section"><h2>Business details</h2><div class="notice">Non-VAT businesses never charge VAT. Registered vendors can select standard-rated, zero-rated or exempt supplies for the whole document. Mixed tax treatments require separate invoices. Review your tax treatment with your accountant.</div><div class="error" id="settings-error" role="alert"></div>${businessFields(state.business)}<label class="check-row"><input type="checkbox" name="nonVat" ${state.business.nonVat?'checked':''}><span>My business is not VAT registered.</span></label><div class="field"><label for="business-vat">VAT registration number (registered vendors only)</label><input id="business-vat" name="vatNumber" pattern="4[0-9]{9}" maxlength="10" value="${esc(state.business.vatNumber||'')}" placeholder="4xxxxxxxxx"></div></div><div class="form-section actions"><button class="btn primary" type="submit">Save business details</button><span class="small muted">Stored in this browser only.</span></div></form></section><section class="panel"><div class="form-section"><h2>Your data, in your hands.</h2><p class="form-note">Records live in this browser’s device storage. There is no cloud sync or automatic backup. Clearing site data, using a different browser, or losing this device can remove access to your records. Backups contain customer and financial details: store them safely.</p><div class="actions section-gap">${btn('Export JSON backup','backup',false,'download')+btn('Encrypted backup','secure-backup',false,'lock')}${btn('Restore backup','restore',false,'up')}${btn('Recover before last restore','recover')}${btn('Try sample workspace','demo')+btn('Switch business','businesses')+btn('Install app','install')}</div><p class="form-note section-gap">CSV exports are useful for spreadsheets. JSON backups are the format that can restore your full workspace.</p><p class="form-note" id="storage-info">${offlineMessage()}</p></div></section><section class="panel"><div class="form-section"><h2>A focused workspace · v0.4.0</h2><p class="form-note">Invoices and quotes, VAT options, discounts and deposits, credit notes, receipts, customer statements, monthly draft schedules, payment reminders, bank CSV matching, expenses and cash reports, encrypted backups and separate businesses. No paid API is required.</p><p class="form-note">Email and WhatsApp open your own apps. InvoiceFlow cannot confirm delivery, track opens, or receive payments. Optional payment links open your provider’s checkout. Payments still need to be verified and recorded manually. There is no subscription or automatic delivery service.</p></div></section></div>`}
function editorPage(){const i=route.id?(route.quote?state.quotes||[]:state.invoices).find(i=>i.id===route.id):null;if(i&&i.state!=='draft'){route={page:route.quote?'quote':'invoice',id:i.id};return route.page==='quote'?quotePage():invoicePage()}if(!editLines.length)editLines=i?structuredClone(i.lines):[{description:'',quantity:100,price:0}];return `${heading(i?`Edit ${esc(i.number)}`:route.quote?'Prepare a quote.':'Let’s make an invoice.','Clear details. Easy to pay.',btn('Preview document','preview-document')+btn('Cancel','cancel-editor'),'A NEW PAYDAY STARTS HERE')}<form id="invoice-form"><div class="editor-grid"><div><section class="panel"><div class="form-section"><h3>Who’s it for?</h3><div class="error" id="invoice-error" role="alert"></div><div class="field"><label for="invoice-customer">Customer *</label><select id="invoice-customer" name="customerId" required><option value="">Choose a customer</option>${state.customers.map(c=>`<option value="${c.id}" ${i?.customerId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div><button class="link-button small" type="button" data-action="new-customer">+ Add a customer</button></div></div><div class="form-grid"><div class="field"><label for="invoice-date">${route.quote?'Quote date':'Invoice date'} *</label><input type="date" required id="invoice-date" name="date" value="${i?.date||today()}"></div><div class="field"><label for="invoice-due">${route.quote?'Valid until':'Due date'} *</label><input type="date" required id="invoice-due" name="due" value="${i?.due||addDays(today(),14)}"></div></div></div><div class="form-section"><h3>The work you did</h3>${state.items.length?`<div class="field"><label for="saved-item">Add from saved items</label><select id="saved-item"><option value="">Choose an item or service…</option>${state.items.map(item=>`<option value="${item.id}">${esc(item.name)} · ${money(item.price)}</option>`).join('')}</select></div>`:''}<div class="line-header"><span>Description</span><span>Quantity</span><span>Unit price (R)</span><span class="text-right">Total</span><span></span></div><div id="invoice-lines">${lineRows()}</div><button type="button" class="btn small" data-action="add-line">${icon('plus')}Add line item</button></div><div class="form-section"><div class="field mb-0"><label for="invoice-notes">Note for your customer</label><textarea id="invoice-notes" name="notes" maxlength="3000" placeholder="A thank you, project details, payment terms…">${esc(i?.notes??state.business.notes)}</textarea></div></div></section></div><aside class="editor-aside"><section class="panel"><div class="totals-box"><h3>${route.quote?'Quote':'Invoice'} summary</h3><div class="summary-row"><span class="muted">Currency</span><span>ZAR · South African rand</span></div><div class="summary-row"><span class="muted">Tax treatment</span><span>${state.business.nonVat?'Non-VAT':'Registered vendor'}</span></div>${pricingFields(i)}<div class="summary-row total"><span>Total</span><span id="editor-total">${money(safeLineSum())}</span></div><button class="btn primary section-gap" type="submit" style="width:100%">${icon('check')}Save draft</button><p class="form-note">Review and share your invoice before marking it sent. Saving a draft sends nothing.</p></div></section><div class="helper-card"><h3>Keep it simple.</h3><p>Give each item a clear description so your customer knows exactly what they’re paying for.</p><p class="mb-0">Your EFT instructions are added from Settings. Confirm the tax treatment and review the document before issuing it.</p></div></aside></div></form>`}
function safeLineSum(){try{return editLines.reduce((a,l)=>a+lineTotal(l),0)}catch{return 0}}
function lineRows(){return editLines.map((l,n)=>`<div class="invoice-line" data-line="${n}"><label class="line-field line-description"><span class="mobile-field-label">Description</span><input class="line-desc" data-field="description" aria-label="Line ${n+1} description" placeholder="e.g. Website design" maxlength="300" required value="${esc(l.description)}"></label><label class="line-field"><span class="mobile-field-label">Quantity</span><input data-field="quantity" inputmode="decimal" type="number" min="0.01" step="0.01" max="1000000" aria-label="Line ${n+1} quantity" required value="${decimal(l.quantity)}"></label><label class="line-field"><span class="mobile-field-label">Price (R)</span><input data-field="price" inputmode="decimal" type="number" min="0" max="100000000" step="0.01" aria-label="Line ${n+1} price in rand" required value="${decimal(l.price)}"></label><div class="line-field line-result"><span class="mobile-field-label">Total</span><span class="line-total">${money(lineTotal(l))}</span></div><button type="button" class="icon-btn" data-remove-line="${n}" aria-label="Remove line ${n+1}" ${editLines.length===1?'disabled':''}>${icon('close')}</button></div>`).join('')}
function readLines(){return [...document.querySelectorAll('.invoice-line')].map(row=>({description:row.querySelector('[data-field=description]').value.trim(),quantity:qty(row.querySelector('[data-field=quantity]').value),price:cents(row.querySelector('[data-field=price]').value)}))}
function invoiceDocument(i){return `<article class="detail-paper template-${esc(i.template||'classic')}"><div class="invoice-top"><div><div class="invoice-title">${i.kind==='quote'?'QUOTE':i.kind==='credit'?'CREDIT NOTE':i.business.nonVat===false?'TAX INVOICE':'INVOICE'}${i.state==='draft'?' · DRAFT':i.state==='void'?' · VOID':''}</div><strong>${esc(i.number)}</strong><div class="address section-gap">${esc(i.business.name)}${i.business.address?'\n'+esc(i.business.address):''}${i.business.email?'\n'+esc(i.business.email):''}${i.business.phone?'\n'+esc(i.business.phone):''}${i.business.vatNumber?'\nVAT: '+esc(i.business.vatNumber):''}</div></div><div class="text-right"><div class="doc-label">${i.kind==='quote'?'Quoted total':'Amount due'}</div><div class="invoice-title">${money(i.state==='void'?0:balance(i))}</div><div class="address">South African rand · ZAR</div></div></div><div class="invoice-parties"><div><div class="doc-label">${i.kind==='quote'?'Prepared for':'Bill to'}</div><strong>${esc(i.customer.name)}</strong><div class="address">${esc(i.customer.address)}${i.customer.email?'\n'+esc(i.customer.email):''}${i.customer.vatNumber?'\nVAT: '+esc(i.customer.vatNumber):''}</div></div><div><div class="summary-row"><span class="muted">${i.kind==='quote'?'Quote date':'Invoice date'}</span><span>${date(i.date)}</span></div><div class="summary-row"><span class="muted">${i.kind==='quote'?'Valid until':'Due date'}</span><span>${date(i.due)}</span></div></div></div><div class="table-wrap"><table class="invoice-detail-lines"><thead><tr><th>Description</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Amount</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td style="white-space:pre-line;overflow-wrap:anywhere">${esc(l.description)}</td><td class="num">${Number(decimal(l.quantity))}</td><td class="num">${money(l.price)}</td><td class="num">${money(lineTotal(l))}</td></tr>`).join('')}</tbody></table></div><div class="doc-totals">${documentBreakdown(i)}<div class="summary-row"><span>${i.kind==='quote'?'Quote':'Invoice'} total</span><strong>${money(total(i))}</strong></div><div class="summary-row"><span class="muted">Payments recorded</span><span>${money(paid(i))}</span></div><div class="summary-row"><span>Credit notes</span><span>${money(credited(i))}</span></div><div class="summary-row total"><span>${i.kind==='quote'?'Quoted total':'Amount due'}${i.state==='void'?' · voided':''}</span><span>${money(i.state==='void'?0:balance(i))}</span></div></div>${i.business.bank?`<div class="doc-label">Payment instructions</div><p class="address">${esc(i.business.bank)}\nReference: ${esc(i.number)}</p>`:''}${i.notes?`<div class="doc-label section-gap">A note for you</div><p class="address">${esc(i.notes)}</p>`:''}${i.payments.some(p=>!p.reversed)?`<div class="doc-label section-gap">Payments recorded</div>${i.payments.filter(p=>!p.reversed).map(p=>`<div class="payment-entry"><span>${date(p.date)} · ${esc(p.reference||'Payment')}</span><strong>${money(p.amount)}</strong></div>`).join('')}`:''}<div class="receipt-note">${i.business.nonVat===false?'VAT treatment: '+esc(i.taxMode||'none')+' · '+((i.vatRate||0)/100)+'%':'VAT is not charged. Supplier is not VAT registered.'}${i.state==='draft'?' Draft only — not yet issued.':''}${i.state==='void'?' This invoice has been voided.':''}</div></article>`}
function paymentHistory(i){if(!i.payments.length)return '';return `<section class="panel"><div class="form-section"><h3>Payment history</h3><p class="form-note">Correct recording errors here. Reversing an entry does not refund or move money.</p>${i.payments.map(p=>`<div class="payment-audit"><div class="summary-row"><strong>${money(p.amount)}</strong><span class="pill ${p.reversed?'void':'paid'}">${p.reversed?'Reversed entry':'Recorded'}</span></div><div class="small muted">${date(p.date)} · ${esc(p.reference||'Payment')}</div>${p.reversed?`<p class="form-note">${esc(p.reversalReason)}</p><p class="small muted">Corrected ${date(p.reversedAt.slice(0,10))}</p>`:`<button class="link-button small" data-reverse-payment="${p.id}">Reverse mistaken entry</button>`}</div>`).join('')}</div></section>`}
function reverseDialog(paymentId){const i=state.invoices.find(i=>i.id===route.id),p=i?.payments.find(p=>p.id===paymentId);if(!p||p.reversed)throw Error('This payment cannot be reversed.');modalForm('Correct a mistaken payment entry',`<div class="notice">Reverse the <strong>${money(p.amount)}</strong> recorded on ${date(p.date)} for <strong>${esc(i.number)}</strong>? Its amount will stop counting as received, including in historical cash summaries. The original entry stays in your audit history. This is not a refund.</div><div class="field"><label for="reversal-reason">Reason for correction *</label><textarea id="reversal-reason" name="reason" required maxlength="300" placeholder="e.g. Duplicate entry; payment was recorded twice"></textarea></div>`,async f=>{await commit(s=>reversePayment(s,i.id,paymentId,f.get('reason')));modal.close();render();toast('Mistaken entry reversed. Balance and cash summaries updated.')},'Reverse entry')}
function offlineMessage(){return offlineState==='ready'?'Offline app files: ready. Device records are not encrypted. Downloaded backups can be password-encrypted.':offlineState==='unavailable'?'Offline caching is unavailable in this browser context. Records still save on this device; export backups regularly.':'Offline app files are being checked. Keep this app open until caching completes. Records are saved on this device.'}
function updateOfflineStatus(){const info=$('#storage-info');if(info)info.textContent=offlineMessage();const footer=$('#offline-footer');if(footer)footer.textContent=offlineReady?'Offline ready · ':''}
function invoicePage(){const i=state.invoices.find(i=>i.id===route.id);if(!i)return heading('Invoice not found.','Return to your invoices to choose another.',btn('All invoices','invoices'));return `${heading(esc(i.number),esc(i.customer.name)+' · '+date(i.date),btn('All invoices','invoices'),'<span>'+status(i).toUpperCase()+'</span>')}<div class="toolbar"><div class="actions">${btn('Download PDF','download-pdf',false,'download')}${btn('Print / save PDF','print-invoice',false,'print')}${i.state!=='void'?btn('Share invoice text','share-invoice',false,'mail'):''}${i.state==='draft'?btn('Edit draft','edit-draft'):''}</div><div class="actions">${i.state==='draft'?btn('Mark sent','issue-invoice',true,'check'):i.state==='issued'&&balance(i)>0?btn('Record payment','payment',true,'plus'):pill(i)}</div></div>${i.state==='draft'?`<div class="notice">Draft invoice. Share or send it using your own app, then mark it sent here. Marking sent locks the invoice details; it does not send an email.</div>`:''}<div class="editor-grid"><section class="panel">${invoiceDocument(i)}</section><aside>${collectionActions(i)}${paymentHistory(i)}<div class="helper-card"><h3>${status(i)==='paid'?'That one’s paid.':status(i)==='overdue'?'Time for a friendly follow-up.':'A clear record of your work.'}</h3><p>${status(i)==='paid'?'This balance is settled by recorded payments and any credit notes. Your cash summary includes actual recorded payments only.':'InvoiceFlow tracks the payments you record. It does not connect to your bank or verify receipt.'}</p><p class="mb-0">Choose <strong>Download PDF</strong> for a file you can attach to an email or message. Browser printing is also available.</p></div>${i.state==='draft'?btn('Delete draft','delete-draft',false,'trash'):i.state==='issued'&&paid(i)===0&&credited(i)===0?btn('Void invoice','void-invoice',false,'close'):''}</aside></div>`}
function modalForm(title,body,onSubmit,label='Save'){modal.setAttribute('aria-labelledby','dialog-title');modal.innerHTML=`<form id="dialog-form"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-btn" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body"><div class="error" id="dialog-error" role="alert"></div>${body}</div><div class="dialog-foot"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">${label}</button></div></form>`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());$('#dialog-form').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;try{await onSubmit(new FormData(event.target));}catch(e){$('#dialog-error').textContent=e.message;$('#dialog-error').scrollIntoView({block:'nearest'});}finally{submit.disabled=false}};modal.showModal()}
function confirmDialog(title,text,action,label='Confirm'){modalForm(title,`<p class="small">${text}</p>`,async()=>{await action();modal.close();render()},label)}
function customerDialog(customerId){const c=state.customers.find(c=>c.id===customerId)||{name:'',email:'',address:''};modalForm(customerId?'Edit customer':'Add a customer',`<div class="field"><label for="customer-name">Customer / business name *</label><input id="customer-name" name="name" required maxlength="200" value="${esc(c.name)}" autocomplete="organization"></div><div class="field"><label for="customer-email">Email</label><input id="customer-email" name="email" type="email" maxlength="254" value="${esc(c.email)}" autocomplete="email"></div><div class="field"><label for="customer-address">Address *</label><textarea id="customer-address" name="address" required maxlength="1500" autocomplete="street-address">${esc(c.address)}</textarea></div><div class="field"><label for="customer-vat">Customer VAT number (if registered)</label><input id="customer-vat" name="vatNumber" pattern="4[0-9]{9}" maxlength="10" value="${esc(c.vatNumber||'')}"></div><p class="form-note">Customer details are stored only in your workspace. No email is sent.</p>`,async f=>{let newId=customerId||id();await commit(s=>{const value={id:newId,name:f.get('name').trim(),email:f.get('email').trim(),address:f.get('address').trim(),vatNumber:f.get('vatNumber').trim()};if(!value.name||!value.address)throw Error('Add a name and address.');if(customerId)s.customers[s.customers.findIndex(c=>c.id===customerId)]=value;else s.customers.push(value)});modal.close();if(route.page==='editor'){const select=$('#invoice-customer');select.innerHTML='<option value="">Choose a customer</option>'+state.customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');select.value=newId}else render();toast('Customer saved.')})}
function itemDialog(itemId){const item=state.items.find(i=>i.id===itemId)||{name:'',price:0};modalForm(itemId?'Edit item':'Save an item or service',`<div class="field"><label for="item-name">Item / service name *</label><input required id="item-name" name="name" maxlength="300" value="${esc(item.name)}"></div><div class="field"><label for="item-price">Unit price (R) *</label><input required id="item-price" name="price" inputmode="decimal" type="number" step="0.01" min="0" max="100000000" value="${decimal(item.price)}"></div>`,async f=>{await commit(s=>{const value={id:itemId||id(),name:f.get('name').trim(),price:cents(f.get('price'))};if(!value.name)throw Error('Add a name.');if(itemId)s.items[s.items.findIndex(i=>i.id===itemId)]=value;else s.items.push(value)});modal.close();render();toast('Item saved.')})}
function expenseDialog(expenseId){const e=state.expenses.find(e=>e.id===expenseId)||{description:'',date:today(),amount:0,category:'Other'};modalForm(expenseId?'Edit expense':'Add an expense',`<div class="field"><label for="expense-desc">What was it for? *</label><input id="expense-desc" name="description" required maxlength="300" placeholder="e.g. Design software subscription" value="${esc(e.description)}"></div><div class="form-grid"><div class="field"><label for="expense-date">Paid on *</label><input type="date" required id="expense-date" name="date" max="${today()}" value="${e.date}"></div><div class="field"><label for="expense-amount">Amount (R) *</label><input inputmode="decimal" type="number" step="0.01" min="0.01" max="100000000" required id="expense-amount" name="amount" value="${e.amount?decimal(e.amount):''}"></div></div><div class="field"><label for="expense-category">Category *</label><select id="expense-category" name="category">${CATEGORIES.map(c=>`<option ${e.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="expense-receipt">Receipt photo or PDF (optional, up to 500 KB)</label><input id="expense-receipt" name="receipt" type="file" accept="image/png,image/jpeg,application/pdf"></div>${e.receipt?`<p class="form-note">Saved attachment: ${esc(e.receipt.name)}. Leave the file field empty to keep it.</p><label class="check-row"><input type="checkbox" name="removeReceipt"><span>Remove the saved attachment</span></label>`:''}${expenseId?`<p class="form-note">To remove this expense, choose <button class="link-button" type="button" id="delete-expense">Delete expense</button>.</p>`:''}`,async f=>{let receipt=e.receipt;const file=f.get('receipt');if(f.get('removeReceipt')==='on')receipt=undefined;if(file?.size){if(f.get('removeReceipt')==='on')throw Error('Choose a replacement receipt or remove the saved receipt, not both.');if(file.size>500000)throw Error('Choose a receipt up to 500 KB.');const bytes=new Uint8Array(await file.arrayBuffer());let encoded='';for(let n=0;n<bytes.length;n+=8192)encoded+=String.fromCharCode(...bytes.subarray(n,n+8192));receipt=validateReceipt({name:file.name.slice(0,150),type:file.type,data:btoa(encoded)})}await commit(s=>{const value=checkExpense({id:expenseId||id(),description:f.get('description').trim(),date:f.get('date'),amount:cents(f.get('amount')),category:f.get('category'),...(receipt?{receipt}:{})});if(expenseId)s.expenses[s.expenses.findIndex(e=>e.id===expenseId)]=value;else s.expenses.push(value)});modal.close();render();toast('Expense saved.')});if(expenseId)$('#delete-expense').onclick=()=>{modal.close();confirmDialog('Delete expense?','This removes the expense from your records and cash summaries.',async()=>{await commit(s=>{s.expenses=s.expenses.filter(e=>e.id!==expenseId)});toast('Expense deleted.')},'Delete expense')}}
function paymentDialog(){const i=state.invoices.find(i=>i.id===route.id);modalForm('Record a payment',`<div class="notice"><strong>${esc(i.number)}</strong> · ${esc(i.customer.name)}<br>Remaining balance: <strong>${money(balance(i))}</strong><br>Only record money you have actually received.</div><div class="form-grid"><div class="field"><label for="payment-amount">Amount received (R) *</label><input id="payment-amount" name="amount" required type="number" inputmode="decimal" min="0.01" step="0.01" max="${decimal(balance(i))}" value="${decimal(balance(i))}"></div><div class="field"><label for="payment-date">Received on *</label><input id="payment-date" name="date" required type="date" min="${i.date}" max="${today()}" value="${today()}"></div></div><div class="field"><label for="payment-ref">Reference / note</label><input id="payment-ref" name="reference" maxlength="150" placeholder="e.g. EFT payment received"></div><p class="form-note">Use a smaller amount for a deposit or partial payment. The balance and cash summary update automatically.</p>`,async f=>{await commit(s=>recordPayment(s,i.id,{amount:cents(f.get('amount')),date:f.get('date'),reference:f.get('reference').trim()}));modal.close();render();toast('Payment recorded. Balance updated.')},'Record payment')}
function shareDialog(){const i=state.invoices.find(i=>i.id===route.id),text=`Hi ${i.customer.name},\n\n${i.state==='draft'?'Draft invoice':'Invoice'} ${i.number} from ${i.business.name}.\nTotal: ${money(total(i))}\nBalance: ${money(balance(i))}\nDue: ${date(i.due)}\n\n${i.lines.map(l=>`${l.description} × ${Number(decimal(l.quantity))} — ${money(lineTotal(l))}`).join('\n')}\n\n${i.business.bank?i.business.bank+'\nReference: '+i.number+'\n\n':''}${i.paymentLink?'Payment link: '+i.paymentLink+'\n\n':''}${i.notes}`;modalForm('Share your invoice',`<p class="small muted">This shares text only. To include the invoice PDF, use Download PDF (or Print / save PDF), then attach it in your email or messaging app.</p><div class="field"><label for="share-text">Message</label><textarea id="share-text" rows="10" readonly>${esc(text)}</textarea></div><div class="actions"><a class="btn" href="mailto:${encodeURIComponent(i.customer.email)}?subject=${encodeURIComponent(`${i.number} · ${i.business.name}`)}&body=${encodeURIComponent(text)}">${icon('mail')}Open email app</a><button class="btn" type="button" id="native-share">Share with another app</button></div><p class="form-note">Nothing is sent automatically. Delivery is handled by your chosen app; InvoiceFlow cannot verify it.</p>`,async()=>{try{await navigator.clipboard.writeText(text);toast('Invoice text copied.');modal.close()}catch{const area=$('#share-text');area.focus();area.select();throw Error('Automatic copy is unavailable. The message is selected; use your browser’s Copy command.')}},'Copy text');$('#native-share').onclick=async()=>{try{if(navigator.share)await navigator.share({title:i.number,text});else{await navigator.clipboard.writeText(text);toast('Sharing unavailable here. Invoice text copied.')}}catch(e){if(e.name!=='AbortError')$('#dialog-error').textContent='Could not share automatically. Select and copy the message above.'}}}
function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function backupText(){return makeBackup(state,mode)}
function backup(){const text=backupText();modalForm('Keep a copy of your records',`<p class="small muted">This backup includes all saved customers, invoices, payment history and expenses in your ${mode==='demo'?'demo':'real'} workspace. Store it safely. Unsaved form changes are not included.</p><div class="field"><label for="backup-text">Full JSON backup</label><textarea id="backup-text" readonly rows="8" spellcheck="false">${esc(text)}</textarea></div><button class="btn" type="button" id="copy-backup">Copy backup text</button><p class="form-note">If downloading is unavailable, copy this text into a .json file. Restore accepts either a file or pasted text.</p>`,async()=>{download(text,`invoiceflow-${mode}-backup-${today()}.json`);toast('Backup download started. Check your downloads.');modal.close()},'Download backup');$('#copy-backup').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('Backup text copied. Store it in a safe file.')}catch{const area=$('#backup-text');area.focus();area.select();toast('Backup text selected. Use your browser’s Copy command.')}}}
function restore(){modalForm('Restore an InvoiceFlow backup',`<p class="small muted">Choose a JSON backup file or paste its full contents. You’ll review the record counts before replacing anything.</p><div class="field"><label for="backup-file">JSON backup file</label><input id="backup-file" name="backupFile" type="file" accept=".json,application/json"></div><div class="field"><label for="restore-password">Password (encrypted backups only)</label><input type="password" id="restore-password" name="password" autocomplete="off"></div><div class="field"><label for="restore-text">Or paste JSON backup</label><textarea id="restore-text" name="backupText" rows="8" spellcheck="false" placeholder="Paste the full InvoiceFlow backup here…"></textarea></div>`,async f=>{const file=f.get('backupFile'),pasted=f.get('backupText').trim();if(file?.size&&pasted)throw Error('Choose a file or pasted text, not both.');if(file?.size>14000000)throw Error('Choose a backup smaller than 10 MB.');if(!file?.size&&!pasted)throw Error('Choose a backup file or paste its contents.');let text=file?.size?await file.text():pasted;try{if(JSON.parse(text).app==='InvoiceFlow encrypted backup')text=await decryptBackup(text,f.get('password'))}catch(e){if(e.message.startsWith('Could not unlock'))throw e}const data=parseBackup(text);modal.close();confirmDialog('Replace this workspace?',`Replace the <strong>${mode==='demo'?'demo':'real'}</strong> workspace with <strong>${data.state.invoices.length} invoices, ${data.state.customers.length} customers, and ${data.state.expenses.length} expenses</strong>? A recovery copy of the current workspace will be saved on this device before replacement.`,async()=>{await commit(s=>{replaceWorkspaceContents(s,data.state)},{checkpoint:true});route={page:'overview'};toast('Backup restored. Your prior workspace is recoverable in Settings.')},'Replace workspace')},'Review backup')}
async function recover(){const previous=await load(mode+'-before-restore');if(!previous){toast('No previous restore to recover in this workspace.');return}validateState(previous);confirmDialog('Recover the previous workspace?',`Restore <strong>${previous.invoices.length} invoices, ${previous.customers.length} customers, and ${previous.expenses.length} expenses</strong> from before the last replacement? The current workspace becomes the new recovery copy.`,async()=>{await commit(s=>{replaceWorkspaceContents(s,previous)},{checkpoint:true});route={page:'overview'};toast('Previous workspace recovered.')},'Recover workspace')}
function importExpenses(){modalForm('Bring your expenses across',`<p class="small muted">Upload a CSV with these four columns. Dates use YYYY-MM-DD, amounts use rand with a decimal point and no currency symbols.</p><code>date,description,amount,category</code><p class="form-note section-gap">Categories: ${CATEGORIES.join(', ')}. Maximum 5,000 rows. Future dates and invalid rows are rejected before anything is saved. Exact duplicates are skipped.</p><div class="field section-gap"><label for="csv-file">Expense CSV *</label><input type="file" id="csv-file" name="csv" accept=".csv,text/csv"></div><div class="field"><label for="csv-paste">Or paste CSV text</label><textarea id="csv-paste" name="csvText" rows="6" spellcheck="false" placeholder="date,description,amount,category"></textarea></div><button type="button" class="btn small" id="csv-template">Download example CSV</button>`,async f=>{const file=f.get('csv'),pasted=f.get('csvText').trim();if(file?.size&&pasted)throw Error('Choose a file or pasted CSV text, not both.');if(!file?.size&&!pasted)throw Error('Choose a CSV file or paste its contents.');if(file?.size>2000000)throw Error('CSV must be smaller than 2 MB.');const rows=expenseCSV(file?.size?await file.text():pasted),seen=new Set(state.expenses.map(fingerprint));const fresh=rows.filter(e=>{const key=fingerprint(e);if(seen.has(key))return false;seen.add(key);return true});modal.close();if(!fresh.length){toast('No new expenses. All rows were duplicates.');return}confirmDialog('Review expense import',`Add <strong>${fresh.length} expenses</strong> totalling <strong>${money(fresh.reduce((a,e)=>a+e.amount,0))}</strong>? ${rows.length-fresh.length} duplicate rows will be skipped. No rows have been saved yet.`,async()=>{await commit(s=>{const existing=new Set(s.expenses.map(fingerprint));s.expenses.push(...fresh.filter(e=>!existing.has(fingerprint(e))))});route={page:'expenses'};toast(`${fresh.length} expenses imported.`)},'Import expenses')},'Review import');$('#csv-template').onclick=()=>download(makeCSV([['date','description','amount','category'],[today(),'Software subscription','149.00','Software'],[today(),'Client meeting transport','85.50','Travel']]),'invoiceflow-expenses-example.csv','text/csv;charset=utf-8')}
function exportInvoices(){const rows=[['invoice','customer','invoice_date','due_date','status','total_ZAR','paid_ZAR','balance_ZAR'],...state.invoices.map(i=>[i.number,i.customer.name,i.date,i.due,status(i),decimal(total(i)),decimal(paid(i)),decimal(i.state==='void'?0:balance(i))])];download(makeCSV(rows),`invoiceflow-invoices-${today()}.csv`,'text/csv;charset=utf-8')}
function exportExpenses(){download(makeCSV([['date','description','amount','category'],...state.expenses.map(e=>[e.date,e.description,decimal(e.amount),e.category])]),`invoiceflow-expenses-${today()}.csv`,'text/csv;charset=utf-8')}
function exportReport(){const s=cashSummary(state,reportStart,reportEnd);download(makeCSV([['metric','amount_ZAR','from','to'],['Payments received',decimal(s.income),reportStart,reportEnd],['Expenses recorded',decimal(s.expenses),reportStart,reportEnd],['Net cash',decimal(s.net),reportStart,reportEnd],['Outstanding (all dates, as of today)',decimal(s.outstanding),'all dates',today()],['Overdue (as of today)',decimal(s.overdue),'all dates',today()]]),`invoiceflow-cash-summary-${reportStart}-${reportEnd}.csv`,'text/csv;charset=utf-8')}
function goto(page,extra={}){if(route.page==='editor'&&page!=='editor'&&!confirm('Leave this invoice? Unsaved draft changes will be lost.'))return;route={page,...extra};editLines=[];search='';render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true})}
const actions={
 'new-invoice':()=>{if(!state.business.name){goto('settings');toast('Save your business details first.');return}goto('editor')},setup:()=>goto('settings'),invoices:()=>goto('invoices'),'cancel-editor':()=>goto(route.id?(route.quote?'quote':'invoice'):(route.quote?'quotes':'invoices'),route.id?{id:route.id}:{}),'new-customer':()=>customerDialog(),'new-item':()=>itemDialog(),'new-expense':()=>expenseDialog(),demo:async()=>{if(route.page==='editor'&&!confirm('Switch workspaces? Unsaved invoice changes will be lost.'))return;await switchMode()},theme:()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('invoiceflow-theme',document.documentElement.dataset.theme)}catch{}const b=$('[data-action=theme]');b.innerHTML=icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')},backup,restore,recover,'import-expenses':importExpenses,'export-invoices':exportInvoices,'export-expenses':exportExpenses,'export-report':exportReport,
 'edit-draft':()=>goto('editor',{id:route.id}),'share-invoice':shareDialog,payment:paymentDialog,
 'download-pdf':async()=>{const b=$('[data-action=download-pdf]'),invoice=structuredClone(state.invoices.find(i=>i.id===route.id));b.disabled=true;try{toast('Preparing your invoice PDF…');const {invoicePDF}=await import('./pdf.js');const bytes=await invoicePDF(invoice);download(bytes,`${invoice.number}.pdf`,'application/pdf');toast('PDF download started. Check your downloads.')}finally{b.disabled=false}},
 'print-invoice':()=>{const i=state.invoices.find(i=>i.id===route.id);$('#print-root').innerHTML=invoiceDocument(i);const title=document.title;document.title=`${i.number} - ${i.customer.name}`;window.print();document.title=title},
 'issue-invoice':()=>{const i=state.invoices.find(i=>i.id===route.id);confirmDialog('Mark invoice as sent?',`Confirm that you shared <strong>${esc(i.number)}</strong> with your customer. This locks its details and starts tracking the outstanding balance. It does not send an email or message.`,async()=>{await commit(s=>issueInvoice(s,i.id));toast('Invoice marked sent. Details are locked.')},'Mark sent')},
 'delete-draft':()=>{const invoiceId=route.id;confirmDialog('Delete this draft?','Its invoice number will not be reused.',async()=>{await commit(s=>{const i=s.invoices.find(i=>i.id===invoiceId);if(i?.state!=='draft')throw Error('Only drafts can be deleted.');if(s.recurring?.some(r=>r.sourceId===invoiceId))throw Error('This draft is the source of a recurring schedule and must be retained.');for(const q of s.quotes||[])if(q.invoiceId===invoiceId)delete q.invoiceId;s.invoices=s.invoices.filter(i=>i.id!==invoiceId)});route={page:'invoices'};toast('Draft deleted.')},'Delete draft')},
 'void-invoice':()=>{const invoiceId=route.id;confirmDialog('Void this unpaid invoice?','The invoice stays in your records, marked void. It will no longer count toward your outstanding balance.',async()=>{await commit(s=>voidInvoice(s,invoiceId));toast('Invoice voided.')},'Void invoice')},
 'add-line':()=>{try{editLines=readLines();if(editLines.length>=100)throw Error('An invoice can have up to 100 lines.');editLines.push({description:'',quantity:100,price:0});$('#invoice-lines').innerHTML=lineRows();updateEditorTotal();}catch(e){failure(e)}}
};
app.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{if(b.dataset.page){goto(b.dataset.page);return}if(b.dataset.action){await actions[b.dataset.action]?.();return}if(b.dataset.receipt){const r=state.expenses.find(e=>e.id===b.dataset.receipt)?.receipt;if(r){validateReceipt(r);download(Uint8Array.from(atob(r.data),x=>x.charCodeAt(0)),r.name,r.type)}return}if(b.dataset.statement){statementDialog(b.dataset.statement);return}if(b.dataset.quoteView){goto('quote',{id:b.dataset.quoteView});return}if(b.dataset.quoteAction){await quoteAction(b.dataset.quoteAction);return}if(b.dataset.generate){let newId;await commit(s=>newId=generateRecurring(s,b.dataset.generate));goto('invoice',{id:newId});toast('Recurring draft created. Review before sending.');return}if(b.dataset.pause){await commit(s=>{const r=s.recurring.find(r=>r.id===b.dataset.pause);r.active=!r.active});render();return}if(b.dataset.creditPdf){await creditPDF(b.dataset.creditPdf);return}if(b.dataset.view){goto('invoice',{id:b.dataset.view});return}if(b.dataset.reversePayment){reverseDialog(b.dataset.reversePayment);return}if(b.dataset.editCustomer){customerDialog(b.dataset.editCustomer);return}if(b.dataset.editItem){itemDialog(b.dataset.editItem);return}if(b.dataset.editExpense){expenseDialog(b.dataset.editExpense);return}if(b.dataset.deleteItem){const itemId=b.dataset.deleteItem;confirmDialog('Delete saved item?','Existing invoices keep their saved line items.',async()=>{await commit(s=>{s.items=s.items.filter(i=>i.id!==itemId)});toast('Item deleted.')},'Delete item');return}if(b.dataset.filter){invoiceFilter=b.dataset.filter;render();return}if(b.dataset.removeLine!==undefined){editLines=readLines();editLines.splice(Number(b.dataset.removeLine),1);$('#invoice-lines').innerHTML=lineRows();updateEditorTotal()}}catch(e){failure(e)}});
function updateEditorTotal(){try{const lines=readLines();let sum=0;lines.forEach((l,n)=>{const amount=lineTotal(l);sum+=amount;document.querySelectorAll('.line-total')[n].textContent=money(amount)});if(sum>10000000000)throw Error('Invoice total is too large.');const f=new FormData($('#invoice-form')),b=breakdown({lines,business:state.business,discount:cents(f.get('discount')||'0'),...taxFields(f.get('tax'))});$('#editor-total').textContent=money(b.total);$('#editor-tax').textContent=`Net ${money(b.net)} · VAT ${money(b.vat)}`}catch{$('#editor-total').textContent='Check amounts'}}
function bindPage(){const sf=$('#settings-form');if(sf)sf.onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{const f=new FormData(sf);await commit(s=>{s.business={name:f.get('name').trim(),email:f.get('email').trim(),phone:f.get('phone').trim(),address:f.get('address').trim(),bank:f.get('bank').trim(),notes:f.get('notes').trim(),nonVat:f.get('nonVat')==='on',vatNumber:f.get('nonVat')==='on'?'':f.get('vatNumber').trim()};if(!s.business.name||!s.business.address)throw Error('Business name and address are required.')});render();toast('Business details saved. You’re ready to invoice.')}catch(error){$('#settings-error').textContent=error.message;$('#settings-error').scrollIntoView({block:'nearest'})}finally{submit.disabled=false}};
const invForm=$('#invoice-form');if(invForm){invForm.addEventListener('input',e=>{updateEditorTotal()});invForm.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const f=new FormData(invForm),lines=readLines();let newId;await commit(s=>{newId=(route.quote?saveQuote:createInvoice)(s,{id:route.id,customerId:f.get('customerId'),date:f.get('date'),due:f.get('due'),notes:f.get('notes'),lines,discount:cents(f.get('discount')||'0'),deposit:cents(f.get('deposit')||'0'),template:f.get('template'),...taxFields(f.get('tax'))})});route={page:route.quote?'quote':'invoice',id:newId};editLines=[];render();window.scrollTo(0,0);toast('Draft saved. Review it before sharing.')}catch(error){$('#invoice-error').textContent=error.message;$('#invoice-error').scrollIntoView({block:'center'});e.submitter.disabled=false}};const select=$('#saved-item');if(select)select.onchange=()=>{try{if(!select.value)return;const item=state.items.find(i=>i.id===select.value);editLines=readLines();const line={description:item.name,quantity:100,price:item.price};if(editLines.length===1&&!editLines[0].description&&editLines[0].price===0)editLines=[line];else if(editLines.length>=100)throw Error('Maximum 100 lines per invoice.');else editLines.push(line);$('#invoice-lines').innerHTML=lineRows();updateEditorTotal();select.value=''}catch(e){failure(e)}}}
const invoiceSearch=$('#invoice-search');if(invoiceSearch)invoiceSearch.oninput=()=>{search=invoiceSearch.value;$('#invoice-results').innerHTML=filteredInvoices()};const rf=$('#report-form');if(rf)rf.onsubmit=e=>{e.preventDefault();const start=$('#report-start').value,end=$('#report-end').value;if(!dateOK(start)||!dateOK(end)||end<start||end>today()){toast('Choose a valid date range ending on or before today.');return}reportStart=start;reportEnd=end;render()}}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
window.addEventListener('beforeunload',e=>{if(route.page==='editor'){e.preventDefault();e.returnValue=''}});
async function boot(){try{db=await openDB();try{const saved=localStorage.getItem('invoiceflow-business');if(/^business-[2-5]$/.test(saved||''))mode=saved}catch{}returnMode=mode;state=await load(mode);if(!state)state=emptyState();validateState(state);render();if(!('serviceWorker'in navigator)){offlineState='unavailable';updateOfflineStatus()}else{navigator.serviceWorker.register('./sw.js').then(async registration=>{const worker=registration.installing||registration.waiting;if(worker&&!['installed','activated'].includes(worker.state)){await new Promise((resolve,reject)=>{worker.addEventListener('statechange',()=>{if(['installed','activated'].includes(worker.state))resolve();else if(worker.state==='redundant')reject(Error('Offline cache installation failed.'))})})}if(registration.waiting)offerUpdate(registration);registration.addEventListener('updatefound',()=>{const next=registration.installing;next?.addEventListener('statechange',()=>{if(next.state==='installed'&&navigator.serviceWorker.controller)offerUpdate(registration)})});await navigator.serviceWorker.ready;const required=['./index.html','./app.js','./core.js','./pdf.js','./vendor/pdf-lib.js','./vendor/fontkit.js','./vendor/DejaVuSans.ttf'];const cached=await Promise.all(required.map(path=>caches.match(new URL(path,location.href).href)));if(cached.some(response=>!response))throw Error('Offline files are incomplete.');offlineReady=true;offlineState='ready';updateOfflineStatus()}).catch(()=>{offlineReady=false;offlineState='unavailable';updateOfflineStatus()})}}catch(e){app.innerHTML=`<div class="error-page"><img src="icon.svg" alt="" width="45"><h1 class="section-gap">We couldn’t open your workspace.</h1><p>${esc(e.message)}</p><p class="muted">No records have been changed. Try reopening this app in a regular browser window. Do not clear site data if you already have records here.</p><button class="btn primary" id="retry">Try again</button></div>`;$('#retry').onclick=()=>location.reload()}}
function taxFields(value){return state.business.nonVat?{vatRate:0,taxMode:'none'}:value==='inclusive'?{vatRate:1500,taxMode:'inclusive'}:value==='zero'?{vatRate:0,taxMode:'exclusive'}:value==='exempt'?{vatRate:0,taxMode:'none'}:{vatRate:1500,taxMode:'exclusive'}}
function pricingFields(i){return `<div class="field section-gap"><label for="invoice-tax">VAT treatment</label><select id="invoice-tax" name="tax" ${state.business.nonVat?'disabled':''}>${[['exclusive','15% VAT · prices exclude VAT'],['inclusive','15% VAT · prices include VAT'],['zero','Zero-rated · 0%'],['exempt','Exempt / no VAT']].map(([v,l])=>`<option value="${v}" ${(i?(i.vatRate===0?(i.taxMode==='none'?'exempt':'zero'):i.taxMode):'exclusive')===v?'selected':''}>${state.business.nonVat?'Non-VAT business':l}</option>`).join('')}</select></div><div class="field"><label for="invoice-discount">Document discount (R, before VAT for exclusive prices)</label><input id="invoice-discount" name="discount" type="number" min="0" step="0.01" value="${decimal(i?.discount||0)}"></div><div class="field"><label for="invoice-deposit">Requested deposit (R, part of total)</label><input id="invoice-deposit" name="deposit" type="number" min="0" step="0.01" value="${decimal(i?.deposit||0)}"></div><div class="field"><label for="invoice-template">Document style</label><select id="invoice-template" name="template">${['classic','minimal','bold'].map(v=>`<option ${i?.template===v?'selected':''}>${v}</option>`).join('')}</select></div><p class="form-note" id="editor-tax">${i?`Net ${money(breakdown(i).net)} · VAT ${money(breakdown(i).vat)}`:'Totals update as you type.'}</p>`}
function documentBreakdown(i){const b=breakdown(i);return `<div class="summary-row"><span>Subtotal</span><span>${money(b.subtotal)}</span></div>${b.discount?`<div class="summary-row"><span>Discount</span><span>−${money(b.discount)}</span></div>`:''}<div class="summary-row"><span>Value excluding VAT</span><span>${money(b.net)}</span></div><div class="summary-row"><span>VAT ${(i.vatRate||0)/100}%</span><span>${money(b.vat)}</span></div>${i.deposit?`<p class="form-note">Requested deposit: ${money(i.deposit)} (included in the total; received payments are recorded separately).</p>`:''}`}
function collectionActions(i){return `<section class="panel"><div class="form-section"><h3>Collect & follow up</h3><div class="actions section-gap">${i.state==='issued'&&balance(i)>0?btn('Payment reminder','reminder')+btn('Issue credit note','credit'):''}${btn('Repeat monthly','recurring')}${paid(i)>0?btn('Download receipt','receipt'):''}${btn('Payment link','payment-link')}</div><p class="form-note">Manual follow-ups and payment recording. A link is not proof of payment.</p>${(i.credits||[]).map(c=>`<div class="payment-audit"><strong>${esc(c.number)} · ${money(c.amount)}</strong><p class="form-note">${esc(c.reason)}</p><button class="btn small" data-credit-pdf="${c.id}">Download credit note</button></div>`).join('')}</div></section>`}
function quotesPage(){return `${heading('Quotes','Agree on the work, then turn acceptance into an invoice.',btn('New quote','new-quote',true,'plus'),'WIN THE NEXT JOB')}<section class="panel">${state.quotes?.length?`<div class="table-wrap"><table><thead><tr><th>Quote / customer</th><th>Valid until</th><th>Status</th><th class="num">Total</th></tr></thead><tbody>${[...state.quotes].reverse().map(q=>`<tr><td><button class="link-button" data-quote-view="${q.id}">${esc(q.number)}</button><div class="muted">${esc(q.customer.name)}</div></td><td>${date(q.due)}</td><td><span class="pill">${q.invoiceId?'Converted':q.state==='sent'&&q.due<today()?'Expired':esc(q.state)}</span></td><td class="num">${money(total(q))}</td></tr>`).join('')}</tbody></table></div>`:empty('invoice','Start with a clear quote','Save a draft, share a PDF, record the customer’s response and convert it once.',btn('New quote','new-quote',true,'plus'))}</section>`}
function quotePage(){const q=state.quotes?.find(q=>q.id===route.id);if(!q)return heading('Quote not found','Choose another quote.');return `${heading(esc(q.number),esc(q.customer.name)+' · '+q.state,btn('All quotes','quotes'))}<div class="toolbar"><div class="actions">${btn('Download quote PDF','quote-pdf',false,'download')}${btn('Share quote text','quote-share')}${q.state==='draft'?btn('Edit quote','edit-quote'):''}${q.state==='draft'?'<button class="btn primary" data-quote-action="sent">Mark shared</button>':q.state==='sent'?'<button class="btn primary" data-quote-action="accepted">Record acceptance</button><button class="btn" data-quote-action="declined">Record decline</button>':q.state==='accepted'?'<button class="btn primary" data-quote-action="convert">'+(q.invoiceId?'Open invoice':'Convert to invoice')+'</button>':''}</div></div><div class="notice">Quote validity ends ${date(q.due)}. Status and acceptance are recorded by you; no online approval or message is sent automatically.</div><section class="panel">${invoiceDocument({...q,kind:'quote'})}</section>`}
async function quoteAction(action){const q=state.quotes.find(q=>q.id===route.id);if(action==='convert'){let invoiceId;await commit(s=>invoiceId=convertQuote(s,q.id));goto('invoice',{id:invoiceId});return}confirmDialog(action==='accepted'?'Record customer acceptance?':'Update quote status?',`You are recording that the customer ${action==='accepted'?'accepted this quote':action==='declined'?'declined this quote':'was sent this quote'}. Keep the original correspondence separately.`,async()=>{await commit(s=>setQuoteState(s,q.id,action));toast('Quote updated.')},'Record status')}
function collectionsPage(){const unpaid=state.invoices.filter(i=>i.state==='issued'&&balance(i)>0),top=state.customers.map(c=>({name:c.name,amount:state.invoices.filter(i=>i.customerId===c.id&&i.state==='issued').reduce((a,i)=>a+paid(i),0)})).filter(c=>c.amount).sort((a,b)=>b.amount-a.amount).slice(0,5);return `${heading('Get paid. Stay on top.','Balances are expected income. Recorded payments are actual receipts.',btn('Match bank CSV','bank-import')+btn('Export ageing CSV','ageing-export',false,'download'),'COLLECTIONS')}<div class="stats">${ageing(state).map(b=>stat(b.label,b.amount,'Current unpaid balance','clock')).join('')}</div><section class="panel"><div class="panel-head"><h2>Invoices to follow up</h2></div>${invoiceTable(unpaid)}</section><section class="panel"><div class="panel-head"><h2>Monthly billing schedules</h2></div><div class="form-section"><p class="form-note">Generate one due occurrence at a time while this app is open. Each creates a draft for review, never an automatic send. Missed months remain due until generated. January’s day is retained after February.</p>${(state.recurring||[]).map(r=>{const i=state.invoices.find(i=>i.id===r.sourceId);return `<div class="list-card"><div><strong>${esc(i.number)} · ${esc(i.customer.name)}</strong><p>Next: ${date(r.nextDate)} · ${r.active?'Active':'Paused'}</p></div><div class="actions"><button class="btn small" data-generate="${r.id}" ${!r.active||r.nextDate>today()?'disabled':''}>Generate due draft</button><button class="btn small" data-pause="${r.id}">${r.active?'Pause':'Resume'}</button></div></div>`}).join('')||'<p>No schedules yet. Open an invoice and choose Repeat monthly.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Top customers by recorded receipts</h2></div><div class="form-section">${top.map(c=>`<div class="summary-row"><span>${esc(c.name)}</span><strong>${money(c.amount)}</strong></div>`).join('')||'<p>No payments recorded yet.</p>'}</div></section>`}
function statementDialog(customerId){const c=state.customers.find(c=>c.id===customerId),rows=customerStatement(state,customerId);modalForm('Customer statement',`<h3>${esc(c.name)}</h3><p class="form-note">Issued invoices, recorded payments and credit notes · as of ${date(today())}.</p><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Due</th><th>Total</th><th>Paid</th><th>Credit</th><th>Balance</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.number)}</td><td>${date(r.due)}</td><td>${money(r.total)}</td><td>${money(r.paid)}</td><td>${money(r.credit)}</td><td>${money(r.balance)}</td></tr>`).join('')}</tbody></table></div><p><strong>Outstanding: ${money(rows.reduce((a,r)=>a+r.balance,0))}</strong></p>`,async()=>{download(makeCSV([['invoice','date','due','total_ZAR','paid_ZAR','credit_ZAR','balance_ZAR'],...rows.map(r=>[r.number,r.date,r.due,decimal(r.total),decimal(r.paid),decimal(r.credit),decimal(r.balance)])]),'customer-statement.csv','text/csv;charset=utf-8');modal.close()},'Download statement CSV')}
function textDialog(title,text){modalForm(title,`<div class="field"><label for="message-text">Message to review and share</label><textarea id="message-text" rows="10">${esc(text)}</textarea></div><p class="form-note">Copy into WhatsApp or email. Nothing is sent automatically.</p>`,async()=>{try{await navigator.clipboard.writeText($('#message-text').value);modal.close();toast('Message copied.')}catch{$('#message-text').select();throw Error('Use your browser’s Copy command on the selected text.')}},'Copy message')}
function recurringDialog(){const i=state.invoices.find(i=>i.id===route.id);modalForm('Repeat this invoice monthly',`<p class="form-note">New drafts use this invoice’s work and current business/customer details. Check tax treatment before issuing each draft.</p><div class="field"><label for="recurring-date">Next billing date</label><input id="recurring-date" name="date" type="date" required min="${addDays(i.date,1)}" value="${addMonth(i.date)}"></div>`,async f=>{await commit(s=>addRecurring(s,i.id,f.get('date')));modal.close();goto('collections');toast('Monthly schedule saved.')},'Save schedule')}
function creditDialog(){const i=state.invoices.find(i=>i.id===route.id);modalForm('Issue a credit note',`<p class="form-note">Adjust the unpaid portion of ${esc(i.number)}. This reduces the balance and preserves the original invoice. It does not refund money. Credits against paid amounts need your accountant’s refund workflow.</p><div class="field"><label for="credit-amount">Credit including VAT (R)</label><input id="credit-amount" name="amount" type="number" min="0.01" step="0.01" max="${decimal(balance(i))}" value="${decimal(balance(i))}" required></div><div class="field"><label for="credit-reason">Reason</label><textarea id="credit-reason" name="reason" required maxlength="500"></textarea></div>`,async f=>{await commit(s=>creditInvoice(s,i.id,cents(f.get('amount')),f.get('reason')));modal.close();render();toast('Credit note issued. Balance updated.')},'Issue credit note')}
async function pdfDownload(i){const {invoicePDF}=await import('./pdf.js');download(await invoicePDF(structuredClone(i)),`${i.number}.pdf`,'application/pdf')}
async function creditPDF(creditId){const source=state.invoices.find(i=>i.credits?.some(c=>c.id===creditId)),c=source.credits.find(c=>c.id===creditId);await pdfDownload({...source,kind:'credit',creditBreakdown:creditTax(source,c.id),state:'issued',number:c.number,date:c.date,due:c.date,lines:[{description:`Credit against ${source.number}: ${c.reason}`,quantity:100,price:c.amount}],discount:0,deposit:0,taxMode:source.vatRate?'inclusive':'none',vatRate:source.vatRate||0,payments:[],credits:[],notes:`Original invoice ${source.number}, dated ${source.date}. Credit reduces the amount owed; no money was refunded.`})}
Object.assign(actions,{
 'new-quote':()=>{if(!state.business.name){goto('settings');toast('Save your business details first.');return}goto('editor',{quote:true})},quotes:()=>goto('quotes'),'edit-quote':()=>goto('editor',{id:route.id,quote:true}),
 'quote-pdf':async()=>pdfDownload({...state.quotes.find(q=>q.id===route.id),kind:'quote'}),
 'quote-share':()=>{const q=state.quotes.find(q=>q.id===route.id);textDialog('Share quote',`Quote ${q.number} from ${q.business.name} for ${q.customer.name}. Total ${money(total(q))}. Valid until ${q.due}. Please reply to confirm acceptance. Download and attach the quote PDF.`)},
 reminder:()=>{const i=state.invoices.find(i=>i.id===route.id);modalForm('Prepare a reminder',`<div class="field"><label for="reminder-tone">Message tone</label><select id="reminder-tone" name="tone"><option value="friendly">Friendly reminder</option><option value="firm">Payment follow-up</option></select></div>`,async f=>{const message=reminderText(i,f.get('tone'));modal.close();textDialog('Payment reminder',message)},'Prepare message')},recurring:recurringDialog,credit:creditDialog,
 'ageing-export':()=>download(makeCSV([['age_bucket','unpaid_ZAR','as_of'],...ageing(state).map(b=>[b.label,decimal(b.amount),today()])]),`invoiceflow-ageing-${today()}.csv`,'text/csv;charset=utf-8'),
 receipt:async()=>{const i=structuredClone(state.invoices.find(i=>i.id===route.id));i.kind='receipt';await pdfDownload(i)},
 'payment-link':()=>{const i=state.invoices.find(i=>i.id===route.id);modalForm('Add your provider payment link',`<p class="form-note">Paste a checkout link created in your PayFast or Yoco account. Never paste API keys. InvoiceFlow neither creates the checkout nor verifies settlement.</p><div class="field"><label for="payment-url">HTTPS checkout URL</label><input type="url" id="payment-url" name="url" required value="${esc(i.paymentLink||'')}" placeholder="https://pay.yoco.com/…"></div>`,async f=>{const url=new URL(f.get('url'));if(url.protocol!=='https:'||url.username||url.password||!['pay.yoco.com','payfast.co.za','www.payfast.co.za','payment.payfast.io'].includes(url.hostname))throw Error('Use an HTTPS checkout link from pay.yoco.com, payfast.co.za or payment.payfast.io.');await commit(s=>s.invoices.find(v=>v.id===i.id).paymentLink=url.href);modal.close();textDialog('Share payment link',`${i.number} · Balance ${money(balance(i))}\n${url.href}\nUse reference ${i.number}. Confirm the amount in the provider checkout.`)},'Save link')}
});

let installPrompt;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
async function businessDialog(){const keys=['live','business-2','business-3','business-4','business-5'],records=await Promise.all(keys.map(load));modalForm('Your businesses',`<p class="form-note">Five separate device workspaces. Export a backup for each business. Demo data remains separate. The selected business is remembered on this device.</p><div class="field"><label for="business-slot">Business workspace</label><select id="business-slot" name="key">${keys.map((key,n)=>`<option value="${key}" ${mode===key?'selected':''}>${n+1}. ${esc(records[n]?.business?.name||'Empty workspace')}</option>`).join('')}</select></div>`,async f=>{if(working||switching)throw Error('Wait for the current save.');const target=f.get('key');if(!keys.includes(target))throw Error('Invalid workspace.');if(target===mode){modal.close();return}switching=true;const previousMode=mode,previousState=state;try{const incoming=await load(target)||emptyState();validateState(incoming);mode=target;state=incoming;returnMode=target;try{localStorage.setItem('invoiceflow-business',target)}catch{}modal.close();route={page:'overview'};editLines=[];render();toast('Business workspace opened.')}catch(e){mode=previousMode;state=previousState;throw e}finally{switching=false}},'Open business')}
function encryptedBackupDialog(){modalForm('Encrypt your backup',`<p class="form-note">AES-256-GCM encryption with a password-derived key. Choose a password of at least 12 characters and keep it safe. Lost passwords cannot be recovered. This encrypts the downloaded backup; device records remain unencrypted.</p><div class="field"><label for="backup-password">Backup password</label><input id="backup-password" name="password" type="password" minlength="12" required autocomplete="new-password"></div><div class="field"><label for="backup-confirm">Confirm password</label><input id="backup-confirm" name="confirm" type="password" minlength="12" required autocomplete="new-password"></div>`,async f=>{if(f.get('password')!==f.get('confirm'))throw Error('Passwords do not match.');const encrypted=await encryptBackup(makeBackup(state,mode),f.get('password'));download(encrypted,`invoiceflow-${mode}-encrypted-${today()}.json`);modal.close();toast('Encrypted backup download started.')},'Download encrypted backup')}
async function bankImportDialog(){modalForm('Match incoming bank payments',`<p class="form-note">Paste incoming transactions only, using date,reference,amount. Amounts are positive rand. No bank connection or automatic reconciliation. Each candidate must be reviewed before it becomes a payment.</p><div class="field"><label for="bank-csv">Bank CSV</label><textarea id="bank-csv" name="csv" rows="8" required placeholder="date,reference,amount"></textarea></div>`,async f=>{if(!globalThis.crypto?.subtle)throw Error('Bank matching needs HTTPS. Open the secure production app.');const rows=bankRows(f.get('csv'));const enriched=await Promise.all(rows.map(async row=>{const encoded=new TextEncoder().encode(JSON.stringify([row.date,row.reference.toLowerCase(),row.amount])),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',encoded))].map(b=>b.toString(16).padStart(2,'0')).join('');return {...row,hash}}));modal.close();reviewBankRows(enriched)},'Review matches')}
function reviewBankRows(rows){const available=rows.filter(row=>!state.invoices.some(i=>i.payments.some(p=>p.bankFingerprint===row.hash)));modalForm('Review bank matches',`<p class="form-note">${rows.length-available.length} previously recorded rows excluded. Identical date, reference and amount are treated as one transaction; genuine duplicates can be recorded manually. Choose an invoice for each payment to record; leave unmatched rows on Skip.</p>${available.map((row,n)=>{const options=state.invoices.filter(i=>i.state==='issued'&&i.date<=row.date&&balance(i)>=row.amount),matched=options.filter(i=>row.reference.toUpperCase().includes(i.number));return `<div class="field"><label for="bank-row-${n}">${date(row.date)} · ${esc(row.reference)} · ${money(row.amount)}</label><select id="bank-row-${n}" name="row-${n}"><option value="">Skip this row</option>${options.map(i=>`<option value="${i.id}" ${matched.length===1&&matched[0].id===i.id?'selected':''}>${esc(i.number)} · ${esc(i.customer.name)} · ${money(balance(i))} due</option>`).join('')}</select></div>`}).join('')}`,async f=>{const selected=available.map((row,n)=>({row,invoiceId:f.get('row-'+n)})).filter(v=>v.invoiceId);if(!selected.length)throw Error('Choose at least one invoice, or Cancel.');await commit(s=>{const seen=new Set();for(const {row,invoiceId} of selected){if(seen.has(row.hash))continue;recordBankPayment(s,invoiceId,{date:row.date,amount:row.amount,reference:row.reference},row.hash);seen.add(row.hash)}});modal.close();render();toast('Reviewed bank payments recorded.')},'Record selected payments')}
function previewDocument(){const form=$('#invoice-form');if(!form.reportValidity())return;const f=new FormData(form),temp=structuredClone(state);const invoiceId=(route.quote?saveQuote:createInvoice)(temp,{id:route.id,customerId:f.get('customerId'),date:f.get('date'),due:f.get('due'),notes:f.get('notes'),lines:readLines(),discount:cents(f.get('discount')||'0'),deposit:cents(f.get('deposit')||'0'),template:f.get('template'),...taxFields(f.get('tax'))});validateState(temp);const invoice=(route.quote?temp.quotes:temp.invoices).find(i=>i.id===invoiceId);modalForm('Document preview · unsaved',invoiceDocument({...invoice,kind:route.quote?'quote':undefined}),async()=>{modal.close()},'Back to editor')}
Object.assign(actions,{businesses:()=>{if(route.page==='editor'&&!confirm('Switch businesses? Unsaved editor changes will be lost.'))return;return businessDialog()},'secure-backup':encryptedBackupDialog,'bank-import':bankImportDialog,'preview-document':previewDocument,install:async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;return}modalForm('Install InvoiceFlow',`<p>On Android Chrome, open the browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>. On iPhone/iPad Safari, use <strong>Share → Add to Home Screen</strong>.</p><p class="form-note">A first online visit is needed to cache app files. Keep backups even when installed. This browser may already have the app installed or may not support installation.</p>`,async()=>modal.close(),'Done')}});

function offerUpdate(registration){const existing=$('#apply-update');if(existing)return;const button=document.createElement('button');button.id='apply-update';button.className='btn small';button.textContent='Apply app update';button.onclick=()=>{if(route.page==='editor'&&!confirm('Apply update? Unsaved editor changes will be lost.'))return;const worker=registration.waiting;if(!worker)return;let reloaded=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloaded){reloaded=true;location.reload()}});worker.postMessage({type:'SKIP_WAITING'})};$('.side-bottom')?.prepend(button)}
boot();
